contract InvMutTest {
    C c;

    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 v) public payable {
        require(true);

        address owner = c.owner(); if (__ESBMC_reverted()) return;
        uint256 beforeSupply = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 beforeBalance = c.balanceOf(owner); if (__ESBMC_reverted()) return;

        bool reverted;
        c.burn(v); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 afterSupply = c.totalSupply(); if (__ESBMC_reverted()) return;

        assert(
            (reverted && beforeBalance < v && afterSupply == beforeSupply) ||
            (!reverted && beforeBalance >= v && afterSupply == beforeSupply - v)
        );
    }

    receive() external payable {}
}

